        let maxY = window.scrollY + document.documentElement.clientHeight - r.height - 8;
        menu.style.left = Math.max(window.scrollX + 8, Math.min(x, maxX)) + 'px';
        menu.style.top = Math.max(window.scrollY + 8, Math.min(y, maxY)) + 'px';
